    #[test]
    fn asan_process_spawn_pipe_roundtrip_no_leak() {
        // `std.process` codegen (phase-8 P1) — the full chained-builder
        // spawn → take-stream → read_to_string → wait roundtrip, looped so
        // LSan catches a per-iteration leak of: the chained `Command` temps
        // (each builder link constructs a fresh Command whose `cmd_args` /
        // `cmd_env` Vecs must drop), the `read_to_string` Ok String (owned
        // buffer adopted from the runtime), or the IoError payloads. The
        // spawn-error arm exercises the `IoError.Other`-free unit-variant
        // Err path (`NotFound` carries no heap).
        assert_clean_asan_run(
            r#"
fn main() {
    let mut i: i64 = 0i64;
    let mut total: i64 = 0i64;
    while i < 8i64 {
        let cmd = Command.new("echo").arg("asan-pipe").env("KARA_ASAN", "1").stdout(Stdio.Piped);
        match cmd.spawn() {
            Ok(child) => {
                match child.stdout() {
                    Some(o) => {
                        match o.read_to_string() {
                            Ok(text) => { total = total + text.len(); }
                            Err(e) => {}
                        }
                    }
                    None => {}
                }
                match child.wait() {
                    Ok(st) => { total = total + st.code; }
                    Err(e) => {}
                }
            }
            Err(e) => {}
        }
        let bad = Command.new("definitely-not-a-binary-kara");
        match bad.spawn() {
            Ok(c) => {}
            Err(e) => { total = total + 1i64; }
        }
        i = i + 1i64;
    }
    println(total.to_string());
}
"#,
            // ("asan-pipe\n".len() == 10, code 0, +1 bad) * 8 = 88
            &["88"],
            "process_spawn_pipe_roundtrip_no_leak",
        );
    }

    #[test]
    fn asan_backpressure_primitives_no_leak() {
        // `Semaphore` / `RateLimiter` each own a heap `Karac*` object behind
        // their `handle_id`; the synthesized single-owner Drop must free it at
        // scope exit. Loop so LSan catches a per-iteration leak of either
        // runtime object (or the per-key bucket map the RateLimiter grows).
        // The RateLimiter key is a fresh f-string String each round, exercising
        // the borrowed-key path (runtime copies the bytes; the arg temp frees).
        assert_clean_asan_run(
            r#"
fn main() {
    let mut i: i64 = 0i64;
    let mut total: i64 = 0i64;
    while i < 40i64 {
        let sem = Semaphore.new(2);
        match sem.acquire(0i64) { Ok(u) => { total = total + 1i64; }, Err(e) => {} }
        match sem.acquire(0i64) { Ok(u) => { total = total + 1i64; }, Err(e) => {} }
        match sem.acquire(0i64) { Ok(u) => { total = total + 1i64; }, Err(e) => {} }
        sem.release();
        let rl = RateLimiter.new_token_bucket(1i64, 2i64);
        let key = f"client-{i}";
        if rl.try_acquire(key) { total = total + 10i64; }
        i = i + 1i64;
    }
    println(total.to_string());
}
"#,
            // per iter: 2 acquires ok (+2), 1 timeout, try_acquire ok (+10) = 12; * 40 = 480
            &["480"],
            "backpressure_primitives_no_leak",
        );
    }

